out = ['/* Icons: add a class cl-i-<name> to a cl-treatment group or a cl-ico heading/paragraph. Generated by make-icons.py. */']
for name, body in ICONS.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">{body}</svg>'
    out.append(f'.cl-i-{name} {{ --cl-icon: url("data:image/svg+xml,{urllib.parse.quote(svg, safe=":/=; ")}"); }}')
(pathlib.Path(__file__).parent / 'src' / 'icons.css').write_text('\n'.join(out) + '\n')
print(len(ICONS), 'icons')
